ruleBookInfo.author:
class.list-unstyled mb-2 book-detail@tag.li.1@tag.a@text
@js:
java.t2s(result)

ruleBookInfo.kind:
@js:
var r = [];
var t = java.getString('class.list-unstyled mb-2 book-detail@tag.li.0@text');
var d = java.getString('class.list-unstyled mb-2 book-detail@tag.li.2@text');
var e = java.getString('@css:.book-detail label:has(.icon-eye)@text');
var h = java.getString('@css:.book-detail label:has(.icon-heart)@text');
if (t) r.push(String(t).replace(/^.+?:\s*/, ''));
if (e) r.push('关注:' + String(e).trim());
if (h) r.push('喜欢:' + String(h).trim());
if (d) r.push('更新:' + String(d).replace(/^.+?:\s*/, ''));
r.join(',')

